//! StyleGAN2-ADA in Burn: NVIDIA's AFHQ Wild generator (foxes, wolves, big
//! cats), generated by build.rs from export.py's ONNX file. A seed makes the
//! noise `z`, the model draws one 512 px picture from it; the same seed always
//! gives the same picture. The truncation (0.7) is fixed in the export.

pub mod model {
    pub mod stylegan2_afhqwild {
        include!(concat!(env!("OUT_DIR"), "/model/stylegan2_afhqwild.rs"));
    }
}

use burn::prelude::*;
use burn::tensor::Bytes;

/// Width and height of every picture.
pub const SIZE: usize = 512;
/// Length of the noise vector `z`.
pub const Z_DIM: usize = 512;
/// The weights' file name (made by build.rs).
pub const FILE: &str = "stylegan2_afhqwild.bpk";

/// A picture: RGB bytes, row by row.
pub struct Image {
    pub width: u32,
    pub height: u32,
    pub rgb: Vec<u8>,
}

/// SplitMix64: small, seeded, the same on every machine.
struct Rng(u64);

impl Rng {
    fn next(&mut self) -> u64 {
        self.0 = self.0.wrapping_add(0x9E37_79B9_7F4A_7C15);
        let mut x = self.0;
        x = (x ^ (x >> 30)).wrapping_mul(0xBF58_476D_1CE4_E5B9);
        x = (x ^ (x >> 27)).wrapping_mul(0x94D0_49BB_1331_11EB);
        x ^ (x >> 31)
    }
    /// In (0, 1]: never 0, so the log below is finite.
    fn uniform(&mut self) -> f64 {
        ((self.next() >> 11) + 1) as f64 / (1u64 << 53) as f64
    }
}

/// `n` numbers from a standard normal distribution (Box-Muller), from `seed`.
pub fn noise(seed: u64, n: usize) -> Vec<f32> {
    let mut rng = Rng(seed);
    let mut out = Vec::with_capacity(n + 1);
    while out.len() < n {
        let (u1, u2) = (rng.uniform(), rng.uniform());
        let r = (-2.0 * u1.ln()).sqrt();
        let a = std::f64::consts::TAU * u2;
        out.push((r * a.cos()) as f32);
        out.push((r * a.sin()) as f32);
    }
    out.truncate(n);
    out
}

/// The model's 1×3×H×W answer in -1..1 to RGB bytes.
fn to_rgb(planar: &[f32], width: usize, height: usize) -> Vec<u8> {
    let plane = width * height;
    let mut rgb = vec![0u8; plane * 3];
    for i in 0..plane {
        for c in 0..3 {
            let v = planar[c * plane + i].clamp(-1.0, 1.0);
            rgb[i * 3 + c] = ((v + 1.0) * 127.5).round() as u8;
        }
    }
    rgb
}

/// The generator, loaded on the graphics chip. The first picture also compiles
/// and tunes the chip's code.
pub struct Generator {
    device: Device,
    model: model::stylegan2_afhqwild::Model,
}

impl Generator {
    /// The model with its weights (the bytes of its .bpk file: wrong bytes
    /// make Burn panic).
    pub fn from_bytes(weights: Vec<u8>) -> Generator {
        let device = Device::default();
        let model = model::stylegan2_afhqwild::Model::from_bytes(Bytes::from_bytes_vec(weights), &device);
        Generator { device, model }
    }

    /// The model with its weights from `dir` (the file named FILE).
    #[cfg(not(target_family = "wasm"))]
    pub fn load(dir: &std::path::Path) -> Result<Generator, String> {
        let weights = std::fs::read(dir.join(FILE)).map_err(|_| format!("{FILE} is not in {}", dir.display()))?;
        Ok(Generator::from_bytes(weights))
    }

    /// The picture for this seed. Native only (it waits for the graphics chip).
    #[cfg(not(target_family = "wasm"))]
    pub fn generate(&self, seed: u64) -> Image {
        let z = Tensor::<2>::from_data(TensorData::new(noise(seed, Z_DIM), [1, Z_DIM]), &self.device);
        let out: Vec<f32> = self.model.forward(z).into_data().try_to_vec::<f32>().expect("f32 output");
        Image { width: SIZE as u32, height: SIZE as u32, rgb: to_rgb(&out, SIZE, SIZE) }
    }

    /// The picture for this seed as a PNG file.
    #[cfg(all(feature = "codec", not(target_family = "wasm")))]
    pub fn png(&self, seed: u64) -> Result<Vec<u8>, String> {
        let img = self.generate(seed);
        use image::ImageEncoder;
        let mut out = Vec::new();
        image::codecs::png::PngEncoder::new(&mut out)
            .write_image(&img.rgb, img.width, img.height, image::ExtendedColorType::Rgb8)
            .map_err(|e| e.to_string())?;
        Ok(out)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn noise_is_standard_normal_and_repeats() {
        let a = noise(42, 100_000);
        assert_eq!(a, noise(42, 100_000));
        assert_ne!(a[..8], noise(43, 8)[..]);
        let mean = a.iter().map(|&v| v as f64).sum::<f64>() / a.len() as f64;
        let var = a.iter().map(|&v| (v as f64 - mean).powi(2)).sum::<f64>() / a.len() as f64;
        assert!(mean.abs() < 0.02 && (var - 1.0).abs() < 0.02, "mean {mean}, variance {var}");
    }

    #[test]
    fn rgb_maps_minus_one_to_one() {
        assert_eq!(to_rgb(&[-1.0, 0.0, 1.0, 2.0, -3.0, 0.5], 2, 1), vec![0, 128, 255, 255, 0, 191]);
    }
}
